#!/usr/bin/env bash
# [P5] Bring the git server up and seed the fixture repositories.
#
# The deploy key arrives as `DEPLOY_PUBKEY`, generated by `05_gitsrv.sh` on the
# docker host so the PRIVATE half never enters an image layer — an image is
# copied, cached and often pushed, and a key baked into one has been handed to
# everybody who can pull it.
set -euo pipefail

DEPLOY_PUBKEY="${DEPLOY_PUBKEY:?DEPLOY_PUBKEY is required}"

install -o git -g git -m 600 /dev/null /home/git/.ssh/authorized_keys
printf '%s\n' "$DEPLOY_PUBKEY" > /home/git/.ssh/authorized_keys
chown git:git /home/git/.ssh/authorized_keys

ssh-keygen -A >/dev/null 2>&1

# ── the fixture repositories ────────────────────────────────────────────────
#
# Two, because the tests need to tell "the ref moved" from "the repo changed":
#   fn.git    one python body, for rppd_function.source_git
#   sql.git   a versioned script directory, for sg_history.source_git (rdbm)
seed_fn() {
    local d=/srv/git/fn.git w=/tmp/fn
    [ -d "$d" ] && return 0
    git init -q --bare "$d"
    git init -q "$w" && cd "$w"
    git config user.email git@gitsrv && git config user.name fixture
    mkdir -p py
    cat > py/hello.py <<'PY'
# fixture function body, served from git
def call(env):
    return "hello from git v1"
PY
    git add -A && git commit -qm "v1"
    git tag -a v1 -m v1
    # a SECOND commit on the branch, so a test can tell a pinned tag from HEAD
    cat > py/hello.py <<'PY'
# fixture function body, served from git
def call(env):
    return "hello from git v2"
PY
    git add -A && git commit -qm "v2"
    git remote add origin "$d" && git push -q --all origin && git push -q --tags origin
    cd / && rm -rf "$w"
}

seed_sql() {
    local d=/srv/git/sql.git w=/tmp/sql
    [ -d "$d" ] && return 0
    git init -q --bare "$d"
    git init -q "$w" && cd "$w"
    git config user.email git@gitsrv && git config user.name fixture
    mkdir -p schema
    echo "create table if not exists git_seeded (id int primary key, v text);" \
        > schema/001_init.sql
    echo "insert into git_seeded values (1,'from git') on conflict do nothing;" \
        > schema/002_seed.sql
    git add -A && git commit -qm "v1"
    git tag -a v1 -m v1
    git remote add origin "$d" && git push -q --all origin && git push -q --tags origin
    cd / && rm -rf "$w"
}

seed_fn
seed_sql
chown -R git:git /srv/git
echo "[gitsrv] repositories: $(ls /srv/git | tr '\n' ' ')"

# Not `exec`, for the same reason the node entrypoint is not: when sshd exits
# the container must stay up so `docker logs` still has the evidence.
/usr/sbin/sshd -D -e || echo "[gitsrv] sshd exited $? - container held open"
sleep infinity
